// Generated pictures: when the pack has no picture of the thing the video is
// about, the editing agent asks for one with `cutroom image new`. The picture
// is generated by the author's own Codex CLI (ChatGPT subscription, its image
// generation tool), in the pack's picture style, and saved into the version as
// images/<name>.png. Cutroom never calls an image API itself and never sees the
// account's credentials.
import { spawn } from "node:child_process";
import { existsSync, statSync } from "node:fs";
import { copyFile, mkdir, mkdtemp, readdir, rm, stat, writeFile } from "node:fs/promises";
import path from "node:path";
import { agentStatus } from "./agent.js";
import { config } from "./config.js";
import { readJson } from "./cut.js";
import { getSetting, setSetting } from "./db.js";
import { imageSize, versionPack } from "./packs.js";

export const IMAGE_NAME = /^[a-z][a-z0-9-]{0,39}$/;
export const SHAPES = { square: "square 1:1", portrait: "portrait 2:3", landscape: "landscape 3:2" };
export const LIMITS = { min: 1, max: 10, default: 3 };
// One picture may be generated again a couple of times; the cap keeps a run from burning the subscription.
export const REDO_LIMIT = 2;
const TIMEOUT = 5 * 60_000;
const MANIFEST = "images.json";

const DEFAULT_STYLE = "Glossy 3D icon, soft rounded shapes, subtle gradients, soft studio light, no outlines";

/** Settings: { enabled, limit }. On by default; usable only while Codex CLI is signed in. */
function stored() {
  const value = getSetting("imageGenerator", null) ?? {};
  const limit = Number.isInteger(value.limit) ? Math.min(LIMITS.max, Math.max(LIMITS.min, value.limit)) : LIMITS.default;
  return { enabled: value.enabled !== false, limit };
}

export function imagesSnapshot() {
  const { enabled, limit } = stored();
  const codex = agentStatus().codex;
  return { generator: "codex", codexSignedIn: codex, enabled, available: enabled && codex, limit, limits: LIMITS };
}

export function setImageSettings({ enabled, limit } = {}) {
  const current = stored();
  if (limit !== undefined && (!Number.isInteger(limit) || limit < LIMITS.min || limit > LIMITS.max)) throw new Error(`Лимит — целое число от ${LIMITS.min} до ${LIMITS.max}.`);
  setSetting("imageGenerator", { enabled: enabled === undefined ? current.enabled : enabled === true, limit: limit ?? current.limit });
  return imagesSnapshot();
}

const imagesDir = (dir) => path.join(dir, "images");

async function readManifest(dir) {
  const value = await readJson(path.join(imagesDir(dir), MANIFEST)).catch(() => null);
  return Array.isArray(value?.images) ? value : { images: [] };
}

export async function listImages(dir) {
  return (await readManifest(dir)).images;
}

/** The prompt Codex gets: the agent's subject, the pack's picture style and the hard rules. */
export function imagePrompt({ subject, style, shape, background, output }) {
  return [
    "Generate exactly one image with your built-in image generation tool. Do not draw it with code, SVG, HTML or Python, and do not search the web for an image.",
    "",
    `Subject: ${subject}`,
    `Style: ${style}`,
    `Shape: ${SHAPES[shape]}.`,
    background === "transparent"
      ? "Background: fully transparent (PNG with alpha). One subject, centered, with some empty margin, nothing cropped."
      : "Background: a complete scene filling the whole frame.",
    "No text, letters, numbers, logos, watermarks or brand marks in the image. No real, recognizable people.",
    "",
    `Save the result as a PNG file at exactly this path: ${output}`,
    "Then reply with one line: the path. Do nothing else.",
  ].join("\n");
}

function runCodex(prompt, cwd, { signal, onLine = () => {} } = {}) {
  const args = ["exec", "--json", "--skip-git-repo-check", "--dangerously-bypass-approvals-and-sandbox", "-C", cwd, prompt];
  return new Promise((resolve, reject) => {
    const child = spawn("codex", args, { cwd, env: { ...process.env, HOME: config.paths.home, CI: "1" }, stdio: ["ignore", "pipe", "pipe"] });
    let stderr = "";
    let lastError = "";
    const timer = setTimeout(() => child.kill("SIGTERM"), TIMEOUT);
    const abort = () => child.kill("SIGTERM");
    signal?.addEventListener("abort", abort, { once: true });
    let buffer = "";
    child.stdout.on("data", (chunk) => {
      buffer += chunk.toString("utf8");
      let i;
      while ((i = buffer.indexOf("\n")) >= 0) {
        const line = buffer.slice(0, i);
        buffer = buffer.slice(i + 1);
        try {
          const event = JSON.parse(line);
          if (event.type === "turn.failed" || event.type === "error") lastError = String(event.error?.message ?? event.message ?? "");
          if (event.type === "item.completed" && event.item?.type === "agent_message") onLine(event.item.text);
        } catch { /* not JSON */ }
      }
    });
    child.stderr.on("data", (chunk) => { stderr = (stderr + chunk.toString("utf8")).slice(-4000); });
    child.on("error", (error) => { clearTimeout(timer); reject(error); });
    child.on("close", (code) => {
      clearTimeout(timer);
      signal?.removeEventListener("abort", abort);
      resolve({ code, error: lastError || stderr.trim().split("\n").filter(Boolean).pop() || "" });
    });
  });
}

/** Newest picture Codex's image tool saved since `since`: a fallback when it did not copy the file itself. */
async function newestGenerated(since) {
  const root = path.join(config.paths.home, ".codex", "generated_images");
  let best = null;
  for (const session of await readdir(root).catch(() => [])) {
    for (const name of await readdir(path.join(root, session)).catch(() => [])) {
      if (!/\.(png|jpe?g|webp)$/i.test(name)) continue;
      const file = path.join(root, session, name);
      const time = statSync(file).mtimeMs;
      if (time >= since && (!best || time > best.time)) best = { file, time };
    }
  }
  return best?.file ?? null;
}

/**
 * Generate images/<name>.png. `again` replaces an existing picture (a couple of
 * times at most); a new name counts towards the per-version limit.
 */
export async function generateImage(dir, name, { prompt, shape = "square", background = "transparent", again = false, signal, onProgress = () => {} } = {}) {
  if (!IMAGE_NAME.test(String(name ?? ""))) throw new Error("Имя картинки: латиница в нижнем регистре, цифры и дефис, начинается с буквы (server-rack).");
  const subject = String(prompt ?? "").trim();
  if (subject.length < 8) throw new Error("Опишите картинку в --prompt: что на ней, ракурс, настроение (по-английски точнее).");
  if (subject.length > 1200) throw new Error("--prompt длиннее 1200 символов: опишите короче.");
  if (!SHAPES[shape]) throw new Error(`--shape: ${Object.keys(SHAPES).join(", ")}.`);
  if (!["transparent", "scene"].includes(background)) throw new Error("--background: transparent (предмет без фона) или scene (сцена на весь кадр).");
  const settings = imagesSnapshot();
  if (!settings.enabled) throw new Error("Генерация картинок выключена в настройках Cutroom. Бери иллюстрации пакета.");
  if (!settings.codexSignedIn) throw new Error("Codex CLI не подключён: генерация картинок недоступна. Бери иллюстрации пакета.");

  const manifest = await readManifest(dir);
  const existing = manifest.images.find((i) => i.name === name);
  if (existing && !again) throw new Error(`Картинка ${name} уже есть (images/${name}.png). Сделать заново — с --again.`);
  if (!existing && again) throw new Error(`Картинки ${name} ещё нет: --again не нужен.`);
  if (existing && existing.redone >= REDO_LIMIT) throw new Error(`Картинку ${name} уже перегенерировали ${REDO_LIMIT} раза: возьми что есть или иллюстрацию пакета.`);
  if (!existing && manifest.images.length >= settings.limit) throw new Error(`Лимит ролика — ${settings.limit} сгенерированных картинок (${manifest.images.map((i) => i.name).join(", ")}). Используй их снова или иллюстрации пакета.`);

  const pack = await versionPack(dir).catch(() => null);
  const style = pack?.imageStyle || DEFAULT_STYLE;
  await mkdir(imagesDir(dir), { recursive: true });
  // Codex works in an empty folder: the version's own AGENTS.md and files are not its business.
  const work = await mkdtemp(path.join(imagesDir(dir), ".work-"));
  const output = path.join(work, `${name}.png`);
  const started = Date.now();
  try {
    onProgress("Codex генерирует картинку (обычно минута)");
    const result = await runCodex(imagePrompt({ subject, style, shape, background, output }), work, { signal });
    if (signal?.aborted) throw new Error("Отменено");
    const file = existsSync(output) ? output : await newestGenerated(started);
    if (!file) throw new Error(`Codex не вернул картинку${result.error ? `: ${result.error}` : ""}.`);
    const size = await imageSize(file);
    if (!size) throw new Error("Codex вернул не PNG: попробуй ещё раз.");
    const target = path.join(imagesDir(dir), `${name}.png`);
    await copyFile(file, target);
    const entry = {
      name, file: `images/${name}.png`, prompt: subject, shape, background, style,
      width: size.width, height: size.height,
      bytes: (await stat(target)).size,
      generator: "codex",
      createdAt: existing?.createdAt ?? new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      redone: existing ? existing.redone + 1 : 0,
      seconds: Math.round((Date.now() - started) / 1000),
    };
    manifest.images = [...manifest.images.filter((i) => i.name !== name), entry];
    await writeFile(path.join(imagesDir(dir), MANIFEST), `${JSON.stringify(manifest, null, 2)}\n`);
    return entry;
  } finally {
    await rm(work, { recursive: true, force: true });
  }
}
